// Base64-encoded JPEG of the JUDE/Forex AI logo, embedded directly (rather than read from
// /public at request time) so the Satori-rendered icon routes (see pwaIcon.tsx) never need
// a filesystem/network read to produce a favicon/apple-icon/manifest icon. JPEG, not PNG --
// this is a detailed photographic-style image where JPEG compresses roughly 10x smaller
// than PNG for the same visual quality at these render sizes (max 512px).
export const PWA_ICON_DATA_URL = "data:image/jpeg;base64,";
